export const seedRecipes = (): Omit<Recipe, "photos">[] => structuredClone(RECIPES);

export const seedExercises = (): Exercise[] =>
  Object.entries(EX).map(([id, [name_ar, name_en, kind]]) => {
    const places = (["home", "gym"] as const).filter((p) => Object.values(PLAN).some((d) => d[p].includes(id)));
    return { id, name_ar, name_en, kind, places: places.length ? places : ["home", "gym"], video_url: null };
  });

export function defaultMealSlots(): Slot[] {
  const { breakfast, week, snacks } = MEAL_DATA;
  const bf: Card[] = breakfast.map((b) => ({ icon: b.i, lines: [...b.t], note: b.n, ...(b.tag ? { tag: b.tag } : {}) }));
  const sn = (): Card[] => snacks.map(([icon, t]) => ({ icon, lines: [t] }));
  return [
    { id: "bf", name: "الإفطار", icon: "🍳", kind: "choose", options: bf },
    { id: "s1", name: "سناك 1", icon: "🍌", kind: "choose", options: sn() },
    { id: "lu", name: "الغداء", icon: "🍗", kind: "rotation", items: week.map((d) => d[0]) },
    { id: "s2", name: "سناك 2", icon: "🥜", kind: "choose", options: sn() },
    { id: "di", name: "العشاء", icon: "🍲", kind: "rotation", items: week.map((d) => d[1]) },
    { id: "mz", name: "مزيونة 25 غ", icon: "🥤", kind: "fixed", text: "25 غ خلطة مزيونة مع إحدى طرق التحضير" },
    { id: "wa", name: "الماء", icon: "💧", kind: "counter", target: 8 },
  ];
}
